import java.util.*;
public class Solution {
  static long solve(int rows,int cols) {
    emit("Solve a smaller rectangle","dimensions",new int[]{rows,cols});
    if(rows==1||cols==1)return 1;
    return solve(rows-1,cols)+solve(rows,cols-1);
  }
  static int frameCount=0;
  static final int FRAME_LIMIT=12000;
  static String quote(String value) {
    StringBuilder out=new StringBuilder("\"");
    for(char c:value.toCharArray()) {
      switch(c) {
        case '"':out.append("\\\"");
        break;
        case '\\':out.append("\\\\");
        break;
        case '\n':out.append("\\n");
        break;
        case '\r':out.append("\\r");
        break;
        case '\t':out.append("\\t");
        break;
        default:if(c<32)out.append(String.format("\\u%04x",(int)c));
        else out.append(c);
      }
    }
    return out.append('"').toString();
  }
  static String json(Object value) {
    if(value==null)return "null";
    if(value instanceof Number||value instanceof Boolean)return value.toString();
    if(value.getClass().isArray()) {
      List<String> parts=new ArrayList<>();
      for(int i=0;i<java.lang.reflect.Array.getLength(value);i++)parts.add(json(java.lang.reflect.Array.get(value,i)));
      return "["+String.join(",",parts)+"]";
    }
    if(value instanceof Collection<?> values) {
      List<String> parts=new ArrayList<>();
      for(Object v:values)parts.add(json(v));
      return "["+String.join(",",parts)+"]";
    }
    if(value instanceof Map<?,?> values) {
      List<String> parts=new ArrayList<>();
      for(var entry:values.entrySet())parts.add(quote(String.valueOf(entry.getKey()))+":"+json(entry.getValue()));
      return "{"+String.join(",",parts)+"}";
    }
    return quote(value.toString());
  }
  static String display(Object value) {
    if(value!=null&&value.getClass().isArray()) {
      List<String> parts=new ArrayList<>();
      for(int i=0;i<java.lang.reflect.Array.getLength(value);i++)parts.add(display(java.lang.reflect.Array.get(value,i)));
      return "["+String.join(", ",parts)+"]";
    }
    return String.valueOf(value);
  }
  static void emit(String note,Object... pairs) {
    if(++frameCount>FRAME_LIMIT)return;
    Map<String,Object> state=new LinkedHashMap<>();
    for(int i=0;i<pairs.length;i+=2)state.put(String.valueOf(pairs[i]),pairs[i+1]);
    System.out.println("FRAME\t{\"note\":"+quote(note)+",\"state\":"+json(state)+"}");
  }
  public static void main(String[] args) {
    System.out.println("CASE	0");
    frameCount=0;
    emit("Input", "arguments", "3,4");
    Object result0=solve(3,4);
    emit("Return the answer", "result", result0);
    System.out.println("RESULT	"+display(result0));
  }
}

